#define IO_PORT 0x3F8  /* Example: Serial Port Base */
unsigned short port = IO_PORT;
unsigned char value = 0xAA;
int byte_count = 1;

/*
 * Grant I/O access (Requires CAP_SYS_RAWIO or root)
 * Start port, length, enable (1)
 */
ioperm(port, byte_count, 1);

/* Low-level output of a byte */
outb(value, port);

/* Revoke access to the port */
ioperm(port, byte_count, 0);

